			>
				Request Pendaftaran Mokas hanya bisa dibuat oleh CMO atau Pimcab.
			</div>

			<div v-else class="space-y-4">
				<!-- Data Mokas -->
				<section
					class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
				>
					<h2
						class="mb-3 text-sm font-semibold uppercase tracking-wide text-ui-ink-gray-400"
					>
						Data Mokas
					</h2>
					<div class="space-y-4">
						<div>
							<label :class="labelClass"
								>Nama Broker / Mokas
								<span class="text-ui-ink-red-500">*</span></label
							>
							<input v-model="form.nama_mokas" type="text" :class="inputClass" />
						</div>

						<div>
							<label :class="labelClass"
								>Kode Broker <span class="text-ui-ink-red-500">*</span></label
							>
							<input
								v-model="form.kode_mokas"
								type="text"
								maxlength="3"
								autocapitalize="characters"
								placeholder="3 huruf, mis. ABC"
								:class="[inputClass, 'font-mono uppercase']"
