							/>
							<p v-if="kodeDipakai" class="mt-1 text-sm text-ui-ink-red-600">
								Kode Broker {{ form.kode_mokas }} sudah dipakai oleh
								{{ kodeDipakai }}. Gunakan kode lain.
							</p>
							<p
								v-else-if="form.kode_mokas && !kodeValid"
								class="mt-1 text-sm text-ui-ink-red-600"
							>
								Kode Broker harus 3 huruf.
							</p>
						</div>

						<div>
							<label :class="labelClass"
								>Tipe Broker <span class="text-ui-ink-red-500">*</span></label
							>
							<!-- Hanya dua pilihan → tombol berdampingan, bukan dropdown -->
							<div
								class="grid grid-cols-2 gap-2"
								role="radiogroup"
								aria-label="Tipe Broker"
							>
								<button
									v-for="t in opsi.tipe_broker"
									:key="t"
									type="button"
									role="radio"
									:aria-checked="form.tipe_broker === t"
									class="flex min-h-[44px] items-center justify-center gap-2 rounded-lg border px-3 py-2 text-base font-medium transition"
									:class="
										form.tipe_broker === t
											? 'border-primary bg-primary/5 text-primary'
											: 'border-ui-line-gray-300 bg-ui-surface text-ui-ink-gray-600 hover:bg-ui-surface-gray-50'
									"
									@click="form.tipe_broker = t"
								>
									<span
										class="flex h-4 w-4 shrink-0 items-center justify-center rounded-full border-2"
										:class="
											form.tipe_broker === t
												? 'border-primary'
												: 'border-ui-line-gray-300'
										"
									>
										<span
											v-if="form.tipe_broker === t"
											class="h-2 w-2 rounded-full bg-primary"
										/>
									</span>
									{{ t === 'EndUser' ? 'End User' : t }}
								</button>
							</div>
						</div>

						<!-- Internal (hanya tipe Mokas, sama seperti Data Mokas) → radio Ya/Tidak -->
						<div v-if="form.tipe_broker === 'Mokas'">
							<label :class="labelClass">Internal</label>
							<div
								class="grid grid-cols-2 gap-2"
								role="radiogroup"
								aria-label="Internal"
							>
								<button
									v-for="opsiInternal in OPSI_INTERNAL"
									:key="opsiInternal.label"
									type="button"
									role="radio"
									:aria-checked="form.internal === opsiInternal.value"
									class="flex min-h-[44px] items-center justify-center gap-2 rounded-lg border px-3 py-2 text-base font-medium transition"
									:class="
										form.internal === opsiInternal.value
											? 'border-primary bg-primary/5 text-primary'
											: 'border-ui-line-gray-300 bg-ui-surface text-ui-ink-gray-600 hover:bg-ui-surface-gray-50'
									"
									@click="form.internal = opsiInternal.value"
								>
									<span
										class="flex h-4 w-4 shrink-0 items-center justify-center rounded-full border-2"
										:class="
											form.internal === opsiInternal.value
												? 'border-primary'
												: 'border-ui-line-gray-300'
										"
									>
										<span
											v-if="form.internal === opsiInternal.value"
											class="h-2 w-2 rounded-full bg-primary"
										/>
									</span>
									{{ opsiInternal.label }}
								</button>
							</div>
						</div>

						<div>
							<label :class="labelClass"
								>Nama Sesuai KTP <span class="text-ui-ink-red-500">*</span></label
							>
							<input v-model="form.nama_pemilik" type="text" :class="inputClass" />
						</div>

						<div>
							<label :class="labelClass"
								>NIK <span class="text-ui-ink-red-500">*</span></label
							>
							<input
								v-model="form.nik"
								type="text"
								inputmode="numeric"
								maxlength="16"
								placeholder="16 digit"
								:class="inputClass"
								@input="onNik"
							/>
							<p
								v-if="form.nik && !nikValid"
								class="mt-1 text-sm text-ui-ink-red-600"
							>
								NIK harus 16 digit angka.
							</p>
							<div
								v-if="peringatanNik"
								class="mt-2 rounded-lg border border-ui-line-orange-200 bg-ui-surface-orange-50 p-3 text-sm text-ui-ink-orange-800"
							>
								<p class="font-semibold">⚠️ Peringatan</p>
								<p class="whitespace-pre-line">{{ peringatanNik }}</p>
								<p class="mt-1 text-ui-ink-gray-600">
									Request tetap bisa diajukan.
								</p>
							</div>
						</div>

						<div>
							<label :class="labelClass"
								>No HP <span class="text-ui-ink-red-500">*</span></label
							>
							<input
								v-model="form.no_hp"
								type="tel"
								inputmode="tel"
								:class="inputClass"
							/>
						</div>

						<div>
							<label :class="labelClass"
								>Alamat <span class="text-ui-ink-red-500">*</span></label
							>
							<textarea v-model="form.alamat_mokas" rows="3" :class="inputClass" />
						</div>
					</div>
				</section>

				<!-- Rekening -->
				<section
					class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
				>
					<h2
						class="mb-3 text-sm font-semibold uppercase tracking-wide text-ui-ink-gray-400"
					>
						Rekening
					</h2>
					<div class="space-y-4">
						<div>
							<label :class="labelClass"
								>Nama Bank <span class="text-ui-ink-red-500">*</span></label
							>
							<SelectMenu
								v-model="form.nama_bank"
								:options="opsi.bank"
								placeholder="Pilih bank…"
								:btn-class="[inputClass, 'hover:border-primary']"
								option-class="text-base"
							/>
						</div>
						<div>
							<label :class="labelClass"
								>Nomor Rekening <span class="text-ui-ink-red-500">*</span></label
							>
							<input
								v-model="form.nomor_rekening"
								type="text"
								inputmode="numeric"
								:class="inputClass"
							/>
						</div>
					</div>
				</section>

				<!-- Pajak (opsional) -->
				<section
					class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
				>
					<h2
						class="mb-3 text-sm font-semibold uppercase tracking-wide text-ui-ink-gray-400"
					>
						Pajak <span class="font-normal normal-case">(opsional)</span>
					</h2>
					<div class="grid grid-cols-2 gap-3">
						<div>
							<label :class="labelClass">Tax Code</label>
							<input v-model="form.tax_code" type="text" :class="inputClass" />
						</div>
						<div>
							<label :class="labelClass">Tax Rate (%)</label>
							<input
								v-model="form.tax_rate"
								type="number"
								inputmode="decimal"
								min="0"
								step="0.01"
								:class="inputClass"
							/>
						</div>
					</div>
				</section>

				<!-- Dokumen PDF -->
				<section
					class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
				>
					<h2
						class="mb-1 text-sm font-semibold uppercase tracking-wide text-ui-ink-gray-400"
					>
						Dokumen (PDF) <span class="text-ui-ink-red-500">*</span>
					</h2>
					<p class="mb-3 text-sm text-ui-ink-gray-500">
						Satu PDF berisi foto showroom, KTP, buku rekening, dan dokumen lainnya.
					</p>
					<input
						ref="inputFile"
						type="file"
						accept="application/pdf,.pdf"
						class="hidden"
						@change="unggahPdf"
					/>
					<button
						type="button"
						:disabled="mengunggah"
						class="flex w-full items-center gap-3 rounded-xl border border-dashed border-ui-line-gray-300 p-3 text-left transition hover:bg-ui-surface-gray-50 disabled:opacity-60"
						@click="inputFile.click()"
					>
						<span
							class="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-ui-surface-red-100 text-xs font-bold text-ui-ink-red-700"
							>PDF</span
						>
						<span class="min-w-0 flex-1">
							<span class="block truncate font-medium text-ui-ink-gray-900">
								{{ mengunggah ? 'Mengunggah…' : namaPdf || 'Pilih file PDF' }}
							</span>
							<span class="text-sm text-ui-ink-gray-500">
								{{
									form.file_dokumen
										? 'Ketuk untuk mengganti'
										: `Maksimal ${MAKS_MB} MB`
								}}
							</span>
						</span>
					</button>
				</section>

				<p
					v-if="errorMsg"
					class="whitespace-pre-line rounded-lg bg-ui-surface-red-50 p-3 text-sm text-ui-ink-red-700"
				>
					{{ errorMsg }}
				</p>
			</div>
		</div>

		<!-- ============ SIMPAN ============ -->
		<div
			v-if="siap && bolehBuat"
			class="fixed inset-x-0 bottom-0 z-30 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3"
			style="padding-bottom: calc(0.75rem + env(safe-area-inset-bottom))"
		>
			<div class="app-container-narrow">
				<button
					type="button"
					:disabled="!bisaSimpan || menyimpan"
					class="min-h-[44px] w-full rounded-lg bg-primary px-4 py-2 text-base font-semibold text-ui-onPrimary transition hover:bg-primary/90 disabled:opacity-50"
					@click="simpan"
				>
					{{ menyimpan ? 'Menyimpan…' : 'Simpan sebagai Draft' }}
				</button>
			</div>
		</div>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { notifySuccess } from '../composables/toast'
import SelectMenu from '../components/SelectMenu.vue'

const API = '/api/method/juragan.api.portal.request_mokas'
const MAKS_MB = 4

const router = useRouter()

const OPSI_INTERNAL = [
	{ label: 'Ya', value: true },
	{ label: 'Tidak', value: false },
]

const labelClass = 'mb-1 block text-sm font-medium text-ui-ink-gray-500'
const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

const form = reactive({
	nama_mokas: '',
	kode_mokas: '',
	tipe_broker: 'Mokas',
	internal: false,
	nama_pemilik: '',
	nik: '',
	no_hp: '',
	alamat_mokas: '',
	nama_bank: '',
	nomor_rekening: '',
	tax_code: '',
	tax_rate: '',
	file_dokumen: '',
})

const opsi = reactive({ bank: [], tipe_broker: ['Mokas', 'EndUser'] })
const siap = ref(false)
const bolehBuat = ref(false)
const inputFile = ref(null)
const namaPdf = ref('')
const mengunggah = ref(false)
const menyimpan = ref(false)
const errorMsg = ref('')
const peringatanNik = ref('')
const kodeDipakai = ref('')

const nikValid = computed(() => /^\d{16}$/.test(form.nik))
const kodeValid = computed(() => /^[A-Z]{3}$/.test(form.kode_mokas))
const bisaSimpan = computed(
	() =>
		form.nama_mokas.trim() &&
		kodeValid.value &&
		!kodeDipakai.value &&
		form.tipe_broker &&
		form.nama_pemilik.trim() &&
		nikValid.value &&
		form.no_hp.trim() &&
		form.alamat_mokas.trim() &&
		form.nama_bank &&
		form.nomor_rekening.trim() &&
		form.file_dokumen &&
		!mengunggah.value
)

function pesanError(json, res) {
	try {
		if (json && json._server_messages) {
			return JSON.parse(json._server_messages)
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
				.replace(/<[^>]+>/g, '')
		}
	} catch (e) {
		/* abaikan */
	}
	return (json && (json.exception || json.message)) || `HTTP ${res.status}`
}

async function panggil(method, params) {
	const q = new URLSearchParams(params)
	const res = await fetch(`${API}.${method}?${q.toString()}`, {
		method: 'GET',
		credentials: 'include',
		headers: { Accept: 'application/json' },
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(pesanError(json, res))
	return json.message
}

// ---- Cek NIK & Kode Broker selagi mengetik (sama dengan peringatan di desk) ----
let timerNik = null
function onNik() {
	form.nik = form.nik.replace(/\D/g, '')
	clearTimeout(timerNik)
	peringatanNik.value = ''
	if (!nikValid.value) return
	timerNik = setTimeout(async () => {
		try {
			peringatanNik.value =
				(await panggil('cek_isian', { nik: form.nik }))?.peringatan_nik || ''
		} catch (e) {
			peringatanNik.value = ''
		}
	}, 300)
}

let timerKode = null
function onKode() {
	form.kode_mokas = form.kode_mokas.toUpperCase().replace(/[^A-Z]/g, '')
	clearTimeout(timerKode)
	kodeDipakai.value = ''
	if (!kodeValid.value) return
	timerKode = setTimeout(async () => {
		try {
			kodeDipakai.value =
				(await panggil('cek_isian', { kode_mokas: form.kode_mokas }))?.kode_dipakai || ''
		} catch (e) {
			kodeDipakai.value = ''
		}
	}, 300)
}

// ---- Upload PDF: diunggah dulu, ditautkan server saat request tersimpan ----
async function unggahPdf(e) {
	const file = e.target.files?.[0]
	e.target.value = ''
	if (!file) return
	errorMsg.value = ''
	if (!/\.pdf$/i.test(file.name) && file.type !== 'application/pdf') {
		errorMsg.value = 'Dokumen harus berupa file PDF.'
		return
	}
	if (file.size > MAKS_MB * 1024 * 1024) {
		errorMsg.value = `Ukuran file maksimal ${MAKS_MB} MB.`
		return
	}
	mengunggah.value = true
	try {
		const fd = new FormData()
		fd.append('file', file, file.name)
		fd.append('is_private', '1')
		const res = await fetch('/api/method/upload_file', {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(pesanError(json, res))
		form.file_dokumen = json.message?.file_url || ''
		namaPdf.value = file.name
	} catch (err) {
		errorMsg.value = err.message || 'Gagal mengunggah PDF.'
	} finally {
		mengunggah.value = false
	}
}

async function simpan() {
	if (!bisaSimpan.value || menyimpan.value) return
	menyimpan.value = true
	errorMsg.value = ''
	try {
		const data = { ...form, internal: form.internal && form.tipe_broker === 'Mokas' ? 1 : 0 }
		if (data.tax_rate === '') data.tax_rate = null
		const res = await fetch(`${API}.buat_request`, {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ data }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(pesanError(json, res))
		const nama = json.message?.name
		notifySuccess(
			`Request ${nama} tersimpan sebagai Draft. Periksa lalu tekan "Ajukan Approval".`
		)
		router.replace({ name: 'RequestMokasDetail', params: { name: nama } })
	} catch (e) {
		errorMsg.value = e.message || String(e)
	} finally {
		menyimpan.value = false
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	try {
		const data = await panggil('get_opsi_form', {})
		bolehBuat.value = !!data?.boleh_buat
		opsi.bank = data?.bank || []
		if (data?.tipe_broker?.length) opsi.tipe_broker = data.tipe_broker
	} catch (e) {
		errorMsg.value = e.message || String(e)
	} finally {
		siap.value = true
	}
})
</script>
